      sourceCode: `function nextWeek(year, month, day) {
  if (!isValidDate(year, month, day)) {
    return 'invalid';
  }

  let newDay = day + 7;
  let newMonth = month;
  let newYear = year;
  const limit = daysInMonth(newYear, newMonth);

  if (newDay > limit) {
    newDay = newDay - limit;
    if (newMonth === 12) {
      newMonth = 1;
      newYear = newYear + 1;
    } else {
      newMonth = newMonth + 1;
    }
  }

  return { year: newYear, month: newMonth, day: newDay };
}`
