      "mbtw.stage.num": "\u968E\u6BB5 {n}",
      "mbtw.stage.model.name": "\u6A21\u578B",
      "mbtw.stage.model.role": "\u628A\u975E\u5F62\u5F0F\u5316\u7684\u898F\u683C\u8F49\u6210\u7CBE\u78BA\u7684\u884C\u70BA\u6A21\u578B\u2014\u2014\u901A\u5E38\u662F\u6709\u9650\u72C0\u614B\u6A5F\u2014\u2014\u63CF\u8FF0\u7CFB\u7D71\u53EF\u80FD\u8655\u65BC\u7684\u72C0\u614B\uFF0C\u4EE5\u53CA\u5728\u72C0\u614B\u9593\u79FB\u52D5\u7684\u4E8B\u4EF6\u3002\u5F8C\u7E8C\u6240\u6709\u6B65\u9A5F\u90FD\u7531\u6B64\u6A21\u578B\u63A8\u5C0E\uFF0C\u6A21\u578B\u932F\u5247\u6E2C\u8A66\u5168\u932F\u3002",
