      "mbtw.model.failure2": "\u6A21\u578B\u6F02\u79FB\uFF1A\u898F\u683C\u6539\u4E86\u4F46\u6A21\u578B\u6C92\u66F4\u65B0\uFF0C\u65BC\u662F\u6E2C\u8A66\u9A57\u8B49\u7684\u662F\u6628\u5929\u7684\u884C\u70BA\u3002",
      "mbtw.criterion.failure1": "\u6E96\u5247\u592A\u5F31\uFF08\u53EA\u505A\u72C0\u614B\u6DB5\u84CB\uFF09\uFF1A\u53EF\u9054\u72C0\u614B\u9593\u640D\u58DE\u7684\u8F49\u79FB\u6703\u6F0F\u6389\u3002",
      "mbtw.criterion.failure2": "\u6E96\u5247\u592A\u5F37\uFF08\u6240\u6709\u8DEF\u5F91\uFF09\uFF1A\u7FA9\u52D9\u96C6\u5408\u7D44\u5408\u7206\u70B8\uFF0C\u5957\u4EF6\u6C38\u9060\u8DD1\u4E0D\u5B8C\u3002",
