      "mbtw.abstract.failure2": "\u5197\u9918\u6E2C\u8A66\uFF1A\u8A31\u591A\u62BD\u8C61\u6E2C\u8A66\u6DB5\u84CB\u540C\u4E00\u500B\u8F49\u79FB\uFF0C\u5957\u4EF6\u81A8\u8139\u537B\u6C92\u589E\u52A0\u6DB5\u84CB\u3002",
      "mbtw.concretize.failure1": "\u5C0D\u61C9\u7F3A\u53E3\uFF1A\u67D0\u500B\u62BD\u8C61\u4E8B\u4EF6\u6C92\u6709\u5177\u9AD4\u5C0D\u61C9\uFF0C\u6E2C\u8A66\u56E0\u6B64\u7121\u6CD5\u57F7\u884C\u3002",
      "mbtw.concretize.failure2": "\u8F38\u5165\u8CC7\u6599\u4E0D\u7576\uFF1A\u6311\u7684\u5177\u9AD4\u503C\u89F8\u767C\u4E86\u62BD\u8C61\u6E2C\u8A66\u672C\u4E0D\u6253\u7B97\u64CD\u7DF4\u7684\u5B88\u885B\u689D\u4EF6\u3002",
      "mbtw.execute.failure1": "\u975E\u6C7A\u5B9A\u6027\uFF1A\u6642\u5E8F\u6216\u975E\u540C\u6B65\u884C\u70BA\u4F7F\u540C\u4E00\u500B\u6E2C\u8A66\u5728\u591A\u6B21\u57F7\u884C\u9593\u6642\u904E\u6642\u6557\u3002",
