      "modelmut.quiz.b": "\u6E2C\u8A66\u5957\u4EF6\u4E00\u5B9A\u592A\u5F31\u2014\u2014\u5B58\u6D3B\u6C38\u9060\u4EE3\u8868\u5C11\u4E86\u4E00\u689D\u6E2C\u8A66\u3002",
      "modelmut.quiz.c": "\u8981\u561B\u5957\u4EF6\u592A\u5F31\u3001\u7121\u6CD5\u8D70\u5230\u6216\u5340\u5206\u9019\u500B\u7A81\u8B8A\uFF0C\u8981\u561B\u5B83\u662F\u7B49\u50F9\u7A81\u8B8A\u9AD4\u3001\u6C92\u6709\u4EFB\u4F55\u6E2C\u8A66\u80FD\u6BBA\u6B7B\u5B83\u3002",
      "modelmut.quiz.d": "\u57FA\u6E96\u6A21\u578B\u932F\u4E86\uFF1B\u5B58\u6D3B\u4EE3\u8868\u539F\u59CB FSM \u6709\u7F3A\u9677\u3002",
      "modelmut.quiz.correct": "\u6B63\u78BA\u3002\u5B58\u6D3B\u8005\u8981\u561B\u662F\u5957\u4EF6\u7F3A\u53E3\uFF08\u52A0\u6E2C\u8A66\u5373\u53EF\u4FEE\u5FA9\uFF09\uFF0C\u8981\u561B\u662F\u7B49\u50F9\u7A81\u8B8A\u9AD4\uFF08\u4F9D\u5B9A\u7FA9\u7121\u6CD5\u6BBA\u6B7B\uFF09\u2014\u2014\u800C\u8981\u5206\u8FA8\u5169\u8005\u9700\u8981\u4EBA\u70BA\u5206\u6790\u3002",
      "modelmut.quiz.wrong": "\u4E0D\u592A\u5C0D\u3002\u5B58\u6D3B\u6709\u5169\u7A2E\u539F\u56E0\uFF1A\u5957\u4EF6\u592A\u5F31\u3001\u7121\u6CD5\u63ED\u9732\u9019\u500B\u7A81\u8B8A\uFF0C\u6216\u5B83\u662F\u7B49\u50F9\u7A81\u8B8A\u9AD4\u3001\u884C\u70BA\u8207\u57FA\u6E96\u5B8C\u5168\u76F8\u540C\u2014\u2014\u56E0\u6B64\u6C92\u6709\u4EFB\u4F55\u6E2C\u8A66\u80FD\u6BBA\u6B7B\u5B83\u3002",
      "modelmut.lab.prompt": "\u6A21\u578B\u7A81\u8B8A\u5206\u6578 100% \u4EE3\u8868\u6E2C\u8A66\u5957\u4EF6\u80FD\u5340\u5206\u6BCF\u4E00\u500B model-mutant\u3002\u9019\u80FD\u4FDD\u8B49\u7A0B\u5F0F\u78BC\u5C64\u7D1A\u7684\u7A81\u8B8A\u5206\u6578\u4E5F\u9AD8\u55CE\uFF1F\u70BA\u4EC0\u9EBC\uFF1F\u6A21\u578B\u62BD\u8C61\u907A\u6F0F\u4E86\u4EC0\u9EBC\uFF1F",
