      "atdd.actor.dev": "Dev",
      "atdd.artifact.discuss": "\u5171\u540C\u7406\u89E3 + \u9A57\u6536\u6E96\u5247",
      "atdd.artifact.distill": "Gherkin scenarios + \u53EF\u57F7\u884C\u7BC4\u4F8B",
